CREATE COLUMN TABLE "TEST_AP"."SPP1" ("ItemCode" NVARCHAR(50) NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "LINENUM" SMALLINT CS_INT NOT NULL , "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Discount" DECIMAL(21,6) CS_FIXED, "ListNum" SMALLINT CS_INT DEFAULT 0, "FromDate" LONGDATE CS_LONGDATE, "ToDate" LONGDATE CS_LONGDATE, "AutoUpdt" NVARCHAR(1) DEFAULT 'Y', "Expand" NVARCHAR(1) DEFAULT 'N', "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("CardCode", "ItemCode", "LINENUM")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "SPP1_CARD" ON "TEST_AP"."SPP1" ( "CardCode" ASC );
CREATE INDEX "SPP1_ITEM" ON "TEST_AP"."SPP1" ( "ItemCode" ASC );
CREATE INDEX "SPP1_CURRENCY" ON "TEST_AP"."SPP1" ( "Currency" ASC )